    var collapsed;
    if (yuluImageMimeType(bytes)) {
        return bytes;
    }
    if (bytes.length < 400) {
        throw new Error("漫画封面解扰前数据长度不足 400 字节");
    }
    collapsed = yuluCollapseComicPrefix(bytes);
    return yuluBytesFromArray(collapsed);
